parameters.jsCode:
// Traduce un evento de Google Calendar a la decision de recordatorio.
// Se ejecuta una vez por evento (runOnceForEachItem).
//
// POR QUE se parsea el telefono del campo "description": el esquema de
// CalendarEvent (src/core/types/ports.ts) no tiene un campo de telefono del
// paciente; calendar.client.ts (createEvent) lo escribe como texto libre
// dentro de la descripcion del evento ("Paciente: <telefono> | ..."). No
// existe tabla de citas en Postgres (la agenda vive solo en Google Calendar),
// asi que este es el UNICO lugar de donde F3 puede recuperar el telefono.
// Es fragil (depende de un formato de texto que no es un contrato), y se
// documenta como vacio detectado en n8n/README.md, no como decision robusta.

const evento = $json;
const clinica = $('Clinicas con calendario configurado').item.json;

const inicioStr = evento.start && (evento.start.dateTime || evento.start.date);
const inicio = inicioStr ? new Date(inicioStr) : null;
const ahora = new Date();

let horasHastaInicio = null;
let ventana = null;
if (inicio) {
  horasHastaInicio = (inicio.getTime() - ahora.getTime()) / 3_600_000;
  // Tolerancia implicita: el cron corre en punto cada hora, asi que redondear
  // al entero mas cercano hace que UN solo tick coincida con cada objetivo
  // (72h, 24h, 3h). Decision documentada en el README (no la fija la
  // especificacion).
  for (const objetivo of [72, 24, 3]) {
    if (Math.round(horasHastaInicio) === objetivo) {
      ventana = objetivo + 'h';
      break;
    }
  }
}

const descripcion = evento.description || '';
const matchTelefono = descripcion.match(/Paciente:\s*([^|]+)/);
const telefonoPaciente = matchTelefono ? matchTelefono[1].trim() : null;

return {
  json: {
    ventana,
    envioProcede: Boolean(ventana) && Boolean(telefonoPaciente),
    calendarEventId: evento.id,
    clinicId: clinica.clinic_id,
    clinicaNombre: clinica.nombre,
    timezone: clinica.timezone,
    telefonoPaciente,
    fechaCitaIso: inicio ? inicio.toISOString() : null,
    horasHastaInicio,
  },
};

