parameters.query:
=INSERT INTO audit_log (clinic_id, evento, detalle_enmascarado)
VALUES (
  '{{ $('Calcular ventana y extraer telefono').item.json.clinicId }}'::uuid,
  'recordatorio_enviado_{{ $('Calcular ventana y extraer telefono').item.json.ventana }}',
  '{{ JSON.stringify({
      calendarEventId: $('Calcular ventana y extraer telefono').item.json.calendarEventId,
      ventana: $('Calcular ventana y extraer telefono').item.json.ventana,
      fechaCitaIso: $('Calcular ventana y extraer telefono').item.json.fechaCitaIso,
      telefonoEnmascarado: String($('Calcular ventana y extraer telefono').item.json.telefonoPaciente).replace(/\d(?=\d{2})/g, '*')
    }).replace(/'/g, "''") }}'::jsonb
);

=SELECT NOT EXISTS (
  SELECT 1 FROM audit_log
  WHERE clinic_id = '{{ $('Calcular ventana y extraer telefono').item.json.clinicId }}'::uuid
    AND evento = 'recordatorio_sin_respuesta_escalado'
    AND detalle_enmascarado->>'calendarEventId' = '{{ $('Calcular ventana y extraer telefono').item.json.calendarEventId }}'
) AS no_escalado_aun;

